def transform_native_cols(df):
    """Stateless: raw categorical strings for CatBoost native cat_features.

    Robustly converts *every* missing representation (real NaN floats,
    None, empty string, "nan"/"none"/"na"/"null" strings) to the sentinel
    ``"__missing__"``. This prevents CatBoost from ever seeing a real ``nan``
    value in a categorical column, which raises
    ``CatBoostError: bad object for id: nan``.
    """
    n = len(df)
    miss = "__missing__"
    bad_tokens = {"nan", "none", "na", "null", "", "nat"}
    out = {}
    for c in CAT_STRING_COLS:
        if c in df.columns and len(df) == n:
            s = df[c]
            # Replace real NaN *before* astype(str) -> no "nan" strings leak.
            s = s.where(s.notna(), miss)
            s = s.astype(str).str.strip()
            # Catch anything that survived as a textual NaN variant.
            s = s.mask(s.str.lower().isin(bad_tokens), miss)
            out[c] = s.to_numpy(dtype=object)
        else:
            out[c] = np.array([miss] * n, dtype=object)
    # Final safety net: force the entire frame to plain strings with no NaNs.
    frame = pd.DataFrame(out).astype(object)
    frame = frame.where(frame.notna(), miss).astype(str)
    return frame
