def _build_cat_frame(df_num, df_cat):
    X = pd.concat([drop_onehot(df_num), df_cat], axis=1)
    # Belt-and-braces: Coerce every cat column to plain string and fill any
    # residual NaN so CatBoost never receives a non-string cat value.
    miss = "__missing__"
    for c in CAT_STRING_COLS:
        if c in X.columns:
            col = X[c]
            col = col.where(col.notna(), miss)
            col = col.astype(str).str.strip()
            col = col.mask(
                col.str.lower().isin({"nan", "none", "na", "null", "", "nat"}),
                miss,
            )
            X[c] = col
    cat_idx = [X.columns.get_loc(c) for c in CAT_STRING_COLS if c in X.columns]
    return X, cat_idx


